window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[170]={"id":"170","numero":170,"titre":"Paludisme","objectifs":[{"id":"170-1","rang":"A","rubrique":"Définitions","titre":"Définition d'un paludisme grave","contenu":"<p>Le <span class=\"kw-def\">paludisme grave</span> est défini par la présence d'<b>au moins un <span class=\"kw-def\">critère clinique</span> ou <span class=\"kw-ttt\">biologique</span> de gravité <span class=\"kw-def\">OMS</span></b> chez un patient infecté par <i><span class=\"kw-etio\">Plasmodium</span></i> (quasi-exclusivement <i><span class=\"kw-etio\">P. falciparum</span></i>, rarement <i><span class=\"kw-etio\">P. knowlesi</span></i> ou <i><span class=\"kw-etio\">P. vivax</span></i>). C'est une <span class=\"kw-alerte\">urgence absolue</span> : la <span class=\"kw-def\">mortalité</span> atteint <span class=\"kw-chiffre\">10-20 %</span> même avec un traitement optimal — le délai de prise en charge conditionne le <span class=\"kw-def\">pronostic</span>.</p>\n<p><span class=\"kw-clinique\">Les</span> critères <span class=\"kw-def\">OMS</span> sont regroupés par <span class=\"kw-alerte\">défaillance</span> d'organe :</p>\n<table >\n  <thead><tr><th>Défaillance</th><th>Critère(s) de gravité OMS</th></tr></thead>\n  <tbody>\n    <tr><td>Neurologique</td><td><ul><li><span class=\"kw-chiffre\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 11</span></li><li><span class=\"kw-clinique\">Convulsions</span></li><li>Prostration</li></ul></td></tr>\n    <tr><td>Respiratoire</td><td><ul><li>PaO₂ <span class=\"kw-chiffre\">&lt; 60 mmHg</span></li><li>SpO₂ <span class=\"kw-chiffre\">&lt; 92 %</span></li><li>FR <span class=\"kw-chiffre\">&gt; 30/min</span></li><li><span class=\"kw-def\">SDRA</span></li></ul></td></tr>\n    <tr><td>Circulatoire</td><td><ul><li>PAS <span class=\"kw-chiffre\">&lt; 80 mmHg</span></li><li>Recours aux <span class=\"kw-ttt\">catécholamines</span></li><li>Hypoperfusion</li></ul></td></tr>\n    <tr><td>Hématologique</td><td><ul><li><span class=\"kw-bio\">Hb</span> adulte <span class=\"kw-chiffre\">&lt; 7 g/dL</span> ou enfant <span class=\"kw-chiffre\">&lt; 5 g/dL</span></li><li><span class=\"kw-clinique\">Hémorragie clinique</span> (extériorisée ou viscérale)</li><li><span class=\"kw-clinique\">Ictère</span> avec <span class=\"kw-bio\">bilirubine</span> <span class=\"kw-chiffre\">&gt; 50 µmol/L</span></li><li>Hémoglobinurie macroscopique</li></ul></td></tr>\n    <tr><td>Rénale</td><td><ul><li><span class=\"kw-bio\">Créatininémie</span> <span class=\"kw-chiffre\">&gt; 265 µmol/L</span></li><li><span class=\"kw-bio\">Urée</span> <span class=\"kw-chiffre\">&gt; 20 mmol/L</span></li><li>Diurèse <span class=\"kw-chiffre\">&lt; 400 mL/24h</span> malgré réhydratation</li></ul></td></tr>\n    <tr><td>Métabolique</td><td><ul><li>Acidose <span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">&lt; 7,35</span> ou <span class=\"kw-bio\">bicarbonates</span> <span class=\"kw-chiffre\">&lt; 15 mmol/L</span></li><li><span class=\"kw-bio\">Lactates</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span></li><li>Hypoglycémie <span class=\"kw-chiffre\">&lt; 2,2 mmol/L</span></li></ul></td></tr>\n    <tr><td>Parasitémie</td><td><ul><li>Adulte <span class=\"kw-chiffre\">&gt; 4 %</span></li><li>Enfant <span class=\"kw-chiffre\">&gt; 10 %</span></li></ul></td></tr>\n  </tbody>\n</table>\n<p><span class=\"kw-alerte\">Aucun accès à <i>P. falciparum</i> ne devrait évoluer vers un paludisme grave si l'accès simple est traité à temps</span> — la gravité signe quasi-toujours un retard diagnostique ou un traitement inadapté.</p>","frequence":1},{"id":"170-2","rang":"A","rubrique":"Étiologie","titre":"Connaître les principales espèces de Plasmodium","contenu":"<p>Le <span class=\"kw-clinique\">paludisme</span> est une <span class=\"kw-def\">protozoose hématozoaire</span> causée par le genre <i><span class=\"kw-etio\">Plasmodium</span></i>. <b>Cinq espèces</b> sont pathogènes pour l'Homme, avec des comportements très différents qu'il faut connaître pour anticiper la gravité, l'incubation et le risque de rechute.</p>\n<table >\n  <thead><tr><th>Espèce</th><th>Zone d'endémie</th><th>Gravité</th><th>Particularité clinique</th></tr></thead>\n  <tbody>\n    <tr><td><i><span class=\"kw-etio\">P. falciparum</span></i></td><td>Afrique subsaharienne ++</td><td><span class=\"kw-alerte\">La seule qui tue</span> (quasi-totalité des accès graves)</td><td><ul><li><span class=\"kw-chiffre\">95 %</span> des cas d'importation en France</li><li>Incubation <span class=\"kw-chiffre\">7 j – 2 mois</span></li><li>Pas d'hypnozoïte → pas de rechute tardive</li></ul></td></tr>\n    <tr><td><i><span class=\"kw-etio\">P. vivax</span></i></td><td>Asie, Amérique latine, Corne de l'Afrique</td><td>Rare gravité, hypoxie possible</td><td><ul><li><span class=\"kw-def\">Hypnozoïtes hépatiques</span> → rechutes jusqu'à <span class=\"kw-chiffre\">3 ans</span></li><li>Nécessite <span class=\"kw-ttt\">primaquine</span> pour éradiquer</li></ul></td></tr>\n    <tr><td><i><span class=\"kw-etio\">P. ovale</span></i></td><td>Afrique de l'Ouest, Asie SE</td><td>Bénin</td><td><ul><li><span class=\"kw-def\">Hypnozoïtes hépatiques</span> → rechutes jusqu'à <span class=\"kw-chiffre\">3 ans</span></li><li>Même PEC anti-rechute que vivax</li></ul></td></tr>\n    <tr><td><i><span class=\"kw-etio\">P. malariae</span></i></td><td>Afrique, Asie, Amérique du Sud</td><td>Bénin</td><td><ul><li>Incubation très longue (jusqu'à <span class=\"kw-chiffre\">&gt; 10 ans</span>)</li><li>Tropisme rénal (<span class=\"kw-clinique\">syndrome néphrotique</span> chronique)</li></ul></td></tr>\n    <tr><td><i><span class=\"kw-etio\">P. knowlesi</span></i></td><td>Asie du SE (Bornéo, Malaisie)</td><td><span class=\"kw-alerte\">Peut être grave</span> (parasitémies explosives)</td><td><ul><li>Espèce simienne, émergente</li><li>Cycle érythrocytaire court (<span class=\"kw-chiffre\">24 h</span>)</li><li>Aspect frottis = <i>P. malariae</i> (piège ++)</li></ul></td></tr>\n  </tbody>\n</table>\n<p><b>Facteurs génétiques de résistance</b> (à connaître pour expliquer la distribution mondiale) : la <span class=\"kw-def\">drépanocytose hétérozygote A/S</span> confère une <span class=\"kw-alerte\">protection partielle</span> contre <span class=\"kw-clinique\">les</span> formes graves à <i><span class=\"kw-etio\">P. falciparum</span></i> (sélection darwinienne expliquant la <span class=\"kw-def\">prévalence</span> du trait drépanocytaire en Afrique sub-S). Le <span class=\"kw-def\">phénotype Duffy négatif Fy(a-b-)</span>, très fréquent en Afrique de l'Ouest, confère une <span class=\"kw-alerte\">résistance quasi-totale à l'invasion par <i>P. vivax</i></span> — d'où la rareté de <i>P. vivax</i> dans cette zone malgré une endémie majeure de falciparum.</p>\n<p><span class=\"kw-alerte\">Piège classique EDN</span> : confondre <i>P. malariae</i> (rénal) et <i>P. ovale/vivax</i> (rechute). Et <span class=\"kw-ci\">ne jamais</span> oublier <i>P. knowlesi</i> chez un voyageur revenu d'Asie du SE — l'aspect au frottis ressemble à <i>P. malariae</i>, mais le potentiel de gravité est falciparum-like.</p>","frequence":1},{"id":"170-3","rang":"B","rubrique":"Physiopath","titre":"Connaître le cycle parasitaire","contenu":"<p>Le cycle <span class=\"kw-etio\">parasitaire</span> du <i><span class=\"kw-etio\">Plasmodium</span></i> est <span class=\"kw-def\">dixène</span> (deux hôtes obl<span class=\"kw-chiffre\">iga</span>toires : moustique <span class=\"kw-etio\">anophèle femelle</span> + Homme) et se déroule en deux grandes phases.</p>\n        <p><b>1. Cycle sexué sporogonique</b> chez l'<span class=\"kw-etio\">anophèle femelle</span> (≈ <span class=\"kw-chiffre\">15 jours</span>) — <span class=\"kw-clinique\">les</span> gamétocytes ingérés lors d'un repas sanguin fusionnent dans l'intestin du moustique, formant un ookinète puis un oocyste qui libère des sporozoïtes migrant vers les glandes salivaires. Le moustique devient alors infectant.</p>\n        <p><b>2. Cycle asexué schizogonique</b> chez l'Homme, en deux étapes :</p>\n        <ul>\n          <li><span class=\"kw-def\">Schizogonie hépatique</span> (ou exo-érythrocytaire) — asymptomatique, correspond à l'incubation (<span class=\"kw-chiffre\">7-15 j</span>). <span class=\"kw-clinique\">Les</span> sporozoïtes injectés par la piqûre gagnent les hépatocytes, s'y multiplient, puis libèrent des mérozoïtes dans la circulation. Pour <i><span class=\"kw-etio\">P. vivax</span></i> et <i><span class=\"kw-etio\">P. ovale</span></i>, certains parasites restent quiescents sous forme d'<span class=\"kw-def\">hypnozoïtes</span> — origine des rechutes tardives.</li>\n          <li><span class=\"kw-def\">Schizogonie érythrocytaire</span> — responsable des symptômes cliniques cycliques. <span class=\"kw-clinique\">Les</span> mérozoïtes envahissent les hématies, s'y répliquent en <span class=\"kw-chiffre\">48 h</span> (<i><span class=\"kw-clinique\">P. falciparum</span>, vivax, ovale</i>) ou <span class=\"kw-chiffre\">72 h</span> (<i>P. malariae</i>), puis font éclater l'hématie de façon synchrone → libération d'une substance pyrogène → <span class=\"kw-clinique\">accès fébrile intermittent</span> (tierce / quarte). C'est l'<span class=\"kw-def\">hémolyse</span> qui dicte la sémiologie : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-bio\">anémie</span>, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-bio\">thrombopénie</span>.</li>\n        </ul>\n        <p><b>Pourquoi <i><span class=\"kw-etio\">P. falciparum</span></i> est la seule espèce qui tue</b> : deux mécanismes physiopath dictent la gravité. <span class=\"kw-alerte\">(1) Séquestration capillaire viscérale</span> — <span class=\"kw-clinique\">les</span> hématies parasitées par les formes matures de falciparum expriment la protéine <span class=\"kw-def\">PfEMP1</span> à leur surface, qui se lie aux récepteurs endothéliaux (ICAM-1, CD36) et provoque une cyto-adhérence aux capillaires cérébraux, rénaux, pulmonaires, placentaires → ischémie d'organe → <span class=\"kw-clinique\">neuropaludisme</span>, défaillances multiviscérales. <span class=\"kw-alerte\">(2) Invasion de TOUS les stades érythrocytaires</span> (jeunes et matures), contrairement à <i>P. vivax</i>/<i>ovale</i> qui ne parasitent que les <span class=\"kw-bio\">réticulocytes</span> — d'où des <span class=\"kw-alerte\">parasitémies très élevées possibles</span> (&gt;<span class=\"kw-chiffre\"> 20 %</span>) et l'absence d'autolimitation naturelle.</p>","frequence":1},{"id":"170-4","rang":"A","rubrique":"Épidémiologie","titre":"Connaître l'épidémiologie du paludisme","contenu":"<p><b>Échelle mondiale</b> : le <span class=\"kw-clinique\">paludisme</span> est la <span class=\"kw-alerte\">1ère cause de décès parasitaire</span> dans le monde (≈ <span class=\"kw-chiffre\">600 000 morts/an</span> selon l'<span class=\"kw-def\">OMS</span>, dont <span class=\"kw-chiffre\">94 %</span> en Afrique subsaharienne, principalement chez l'enfant <span class=\"kw-chiffre\">&lt; 5 ans</span>). Endémie présente dans plus de <span class=\"kw-chiffre\">80 pays</span> intertropicaux : Afrique subsaharienne (<span class=\"kw-chiffre\">90 %</span> des décès mondiaux), Asie du Sud-Est, Amérique du Sud, Caraïbes, Océanie.</p>\n        <p><b>Échelle France</b> : il s'agit quasi-exclusivement d'un <span class=\"kw-def\">paludisme d'importation</span>. Environ <span class=\"kw-chiffre\">4 000 cas/an</span> diagnostiqués, dont &gt; <span class=\"kw-chiffre\">85 %</span> proviennent d'Afrique subsaharienne francophone, ≈ <span class=\"kw-chiffre\">90 %</span> à <i><span class=\"kw-etio\">P. falciparum</span></i>. <span class=\"kw-chiffre\">10-20 décès/an</span>. <span class=\"kw-clinique\">Les</span> voyageurs migrants visitant la famille (« <span class=\"kw-def\">VFR</span> ») et les nouveaux arrivants sont les plus touchés. <span class=\"kw-alerte\">La déclaration obligatoire ne concerne que les cas autochtones</span> (Guyane, Mayotte, Réunion, Antilles) — <span class=\"kw-alerte\">le paludisme d'importation en métropole n'est PAS une MDO</span>.</p>\n        <p><b>Sources d'information</b> à connaître : <span class=\"kw-def\">BEH</span> (Bulletin Épidémiologique Hebdomadaire) publié chaque année par <span class=\"kw-def\">Santé Publique France</span> et le <span class=\"kw-def\">HCSP</span> (Haut Conseil de la Santé Publique) — recommandations vaccinales et antipaludiques mises à jour annuellement.</p>","frequence":1},{"id":"170-5","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les circonstances qui imposent la recherche d'un paludisme","contenu":"<p><b>Dogme cardinal</b> qui doit être un automatisme aux ECN/EDN comme en pratique :</p>\n        <ul>\n          <li><span class=\"kw-alerte\">Toute fièvre chez un patient doit faire rechercher un séjour en zone d'endémie palustre.</span></li>\n          <li>Toute <span class=\"kw-clinique\">fièvre</span> ou symptôme inexpliqué au décours d'un séjour en zone d'endémie doit faire évoquer le <span class=\"kw-clinique\">paludisme</span>, <span class=\"kw-alerte\">même si un autre foyer infectieux est identifié</span> (<span class=\"kw-clinique\">les</span> co-infections sont fréquentes, ne masquent jamais le paludisme).</li>\n          <li>Une <span class=\"kw-def\">chimioprophylaxie</span> correctement prise <span class=\"kw-alerte\">n'élimine pas le risque à 100 %</span> — la suspicion doit rester intacte.</li>\n        </ul>\n        <p><b>Incubations à connaître</b> pour orienter : minimale <span class=\"kw-chiffre\">7 jours</span> pour <i><span class=\"kw-etio\">P. falciparum</span></i> et <span class=\"kw-chiffre\">10-15 j</span> pour <span class=\"kw-clinique\">les</span> autres espèces ; maximale <span class=\"kw-chiffre\">2 mois</span> pour <i><span class=\"kw-clinique\">P. falciparum</span></i> (<span class=\"kw-chiffre\">95 %</span> des cas), jusqu'à <span class=\"kw-chiffre\">3 ans</span> pour <i><span class=\"kw-etio\">P. vivax</span></i> et <i><span class=\"kw-etio\">P. ovale</span></i> (<span class=\"kw-def\">hypnozoïtes</span>), jusqu'à <span class=\"kw-chiffre\">&gt; 10 ans</span> pour <i><span class=\"kw-etio\">P. malariae</span></i>. <span class=\"kw-alerte\">Donc un voyage en Afrique il y a 6 mois ne rassure pas.</span></p>\n        <p><b>Sémiologie suggestive</b> : <span class=\"kw-clinique\">fièvre</span> (<span class=\"kw-chiffre\">90 %</span>) avec <span class=\"kw-clinique\">frissons</span> et sueurs, <span class=\"kw-clinique\">accès intermittents</span>, <span class=\"kw-clinique\">syndrome pseudo-grippal</span> (<span class=\"kw-clinique\">céphalées</span>, myalgies, nausées/vomissements, diarrhée), <span class=\"kw-clinique\">splénomégalie</span> inconstante, <span class=\"kw-clinique\">ictère</span>. Biologiquement : <span class=\"kw-bio\">thrombopénie</span> quasi-constante (signe d'alerte ++), <span class=\"kw-clinique\">anémie hémolytique</span> (<span class=\"kw-bio\">LDH</span> ↑, <span class=\"kw-bio\">haptoglobine</span> ↓, <span class=\"kw-bio\">bilirubine libre</span> ↑), <span class=\"kw-bio\">CRP</span> souvent <span class=\"kw-chiffre\">&gt; 100 mg/L</span>, cytolyse modérée à prédominance <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-alerte\">absence d'hyperéosinophilie</span> (signe négatif utile). À noter également une <span class=\"kw-bio\">leucopénie</span> fréquente, un possible <span class=\"kw-clinique\">syndrome mononucléosique réactionnel</span>, et une <span class=\"kw-bio\">anémie</span> initialement <span class=\"kw-bio\">arégénérative</span> (avant la reprise réticulocytaire).</p>","frequence":2},{"id":"170-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'un accès palustre (adulte et enfant)","contenu":"<p><span class=\"kw-alerte\">Le diagnostic du paludisme est une urgence biologique absolue</span> : le biologiste doit rendre un résultat en <span class=\"kw-chiffre\">&lt; 2 heures</span>. Le prélèvement (<span class=\"kw-bio\">EDTA</span>) est fait sans attendre un pic fébrile.</p>\n<p>La stratégie repose sur l'association d'une <b>technique sensible + un <span class=\"kw-bio\">frottis mince sanguin</span></b>. Pas une seule technique en aveugle : chacune a ses limites.</p>\n<table >\n  <thead><tr><th>Examen</th><th>Sensibilité</th><th>Parasitémie</th><th>Diagnostic d'espèce</th><th><span class=\"kw-def\">Suivi</span></th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-bio\">Goutte épaisse</span></td><td>Très sensible (gros volume de sang lysé)</td><td>Non</td><td>Non</td><td>Non</td></tr>\n    <tr><td><span class=\"kw-bio\">Frottis mince</span></td><td>Moins sensible</td><td><b>Oui</b> (essentielle pour <span class=\"kw-def\">grade</span> de gravité)</td><td><b>Oui</b></td><td><b>Oui</b> (décroissance J<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>/J</span>7/<span class=\"kw-chiffre\">J28</span>)</td></tr>\n    <tr><td><span class=\"kw-bio\">TDR</span> (<span class=\"kw-def\">HRP-2</span>, <span class=\"kw-def\">pLDH</span>)</td><td>Dépend de la parasitémie (FN si faible)</td><td>Non</td><td>Oui (falciparum, vivax)</td><td>Non (HRP-2 reste + <span class=\"kw-chiffre\">2-6 sem</span>)</td></tr>\n    <tr><td><span class=\"kw-bio\">PCR</span></td><td>Très sensible</td><td>Non</td><td><b>Oui</b></td><td>Non (reste + jusqu'à <span class=\"kw-chiffre\">1 mois</span>)</td></tr>\n  </tbody>\n</table>\n<p><b>Algorithme pratique</b> : si une technique sensible (<span class=\"kw-bio\">goutte épaisse</span> OU <span class=\"kw-bio\">PCR rapide</span>) est disponible → la coupler au <span class=\"kw-bio\">frottis mince</span>. Si indisponible → coupler <b><span class=\"kw-bio\">TDR</span> + <span class=\"kw-bio\">frottis mince</span></b>. Si <span class=\"kw-bio\">TDR</span> positif mais frottis négatif (parasitémie faible) → doute, avis spécialisé, refaire à <span class=\"kw-chiffre\">H+12-24</span>.</p>\n<p><b>Pour évaluer la gravité</b>, prélever en parallèle : <span class=\"kw-bio\">NFS</span>, bilan d'hémolyse (<span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobine</span>, <span class=\"kw-bio\">bilirubine</span>), <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée/créatinine</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">bilan hépatique complet</span>, <span class=\"kw-bio\">GDS artériels avec lactates</span>, <span class=\"kw-bio\">hémocultures aérobies/anaérobies</span> (<span class=\"kw-alerte\">co-infection bactérienne fréquente, ne pas la rater</span>).</p>","frequence":4},{"id":"170-7","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier un accès grave","contenu":"<p>L'évaluation clinico-<span class=\"kw-ttt\">biologique</span> de gravité est <span class=\"kw-alerte\">systématique chez tout patient avec paludisme confirmé</span>, indépendamment de l'apparente « bonne tolérance ». Tout <span class=\"kw-clinique\">paludisme</span> à <i><span class=\"kw-etio\">P. falciparum</span></i> doit être considéré comme potentiellement grave jusqu'à preuve du contraire.</p>\n<p><b>Critères <span class=\"kw-def\">OMS</span> de <span class=\"kw-clinique\">paludisme</span> grave</b> (un seul suffit pour déclencher l'<span class=\"kw-alerte\">hospitalisation</span> en réanimation) :</p>\n<table >\n  <thead><tr><th><span class=\"kw-alerte\">Défaillance</span></th><th>Critère(s) OMS détaillé(s)</th></tr></thead>\n  <tbody>\n    <tr><td>Neurologique</td><td><ul><li><span class=\"kw-chiffre\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 11</span>, obnubilation</li><li><span class=\"kw-clinique\">Confusion</span>, <span class=\"kw-clinique\">convulsions</span></li><li>Prostration</li></ul></td></tr>\n    <tr><td>Respiratoire</td><td><ul><li>PaO₂ <span class=\"kw-chiffre\">&lt; 60 mmHg</span></li><li>SpO₂ <span class=\"kw-chiffre\">&lt; 92 %</span></li><li>FR <span class=\"kw-chiffre\">&gt; 30/min</span></li><li><span class=\"kw-def\">SDRA</span></li></ul></td></tr>\n    <tr><td>Circulatoire</td><td><ul><li>PAS <span class=\"kw-chiffre\">&lt; 80 mmHg</span></li><li>Recours aux <span class=\"kw-ttt\">catécholamines</span></li><li>Signes d'hypoperfusion</li></ul></td></tr>\n    <tr><td>Hématologique</td><td><ul><li><span class=\"kw-clinique\">Hémorragie clinique</span> (extériorisée ou viscérale)</li><li><span class=\"kw-clinique\">Ictère</span> ou <span class=\"kw-bio\">bilirubine</span> <span class=\"kw-chiffre\">&gt; 50 µmol/L</span></li><li><span class=\"kw-clinique\">Hémoglobinurie macroscopique</span></li><li>Anémie profonde : adulte <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">&lt; 7 g/dL</span> ou <span class=\"kw-bio\">Ht</span> <span class=\"kw-chiffre\">&lt; 20 %</span></li><li>Enfant <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">&lt; 5 g/dL</span> ou <span class=\"kw-bio\">Ht</span> <span class=\"kw-chiffre\">&lt; 15 %</span></li></ul></td></tr>\n    <tr><td>Rénal</td><td><ul><li><span class=\"kw-bio\">Créatininémie</span> <span class=\"kw-chiffre\">&gt; 265 µmol/L</span></li><li><span class=\"kw-bio\">Urée</span> <span class=\"kw-chiffre\">&gt; 20 mmol/L</span></li><li>Diurèse <span class=\"kw-chiffre\">&lt; 400 mL/24h</span> malgré réhydratation</li></ul></td></tr>\n    <tr><td>Métabolique</td><td><ul><li>Acidose <span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">&lt; 7,35</span> ou HCO₃⁻ <span class=\"kw-chiffre\">&lt; 15 mmol/L</span></li><li><span class=\"kw-bio\">Lactates</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> (a fortiori <span class=\"kw-chiffre\">&gt; 5</span>)</li><li><span class=\"kw-bio\">Hypoglycémie</span> <span class=\"kw-chiffre\">&lt; 2,2 mmol/L</span></li></ul></td></tr>\n    <tr><td>Parasitémie</td><td><ul><li>Adulte <span class=\"kw-chiffre\">&gt; 4 %</span></li><li>Enfant <span class=\"kw-chiffre\">&gt; 10 %</span></li></ul></td></tr>\n  </tbody>\n</table>\n<p><b>Critères d'<span class=\"kw-alerte\">hospitalisation</span> (sans réanimation)</b> : <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span>, <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">&lt; 10 g/dL</span>, <span class=\"kw-bio\">créatininémie</span> <span class=\"kw-chiffre\">&gt; 150 µmol/L</span>, parasitémie <span class=\"kw-chiffre\">&gt; 2 %</span>.</p>\n<p><b><span class=\"kw-def\">Terrain</span> à risque</b> imposant l'<span class=\"kw-alerte\">hospitalisation</span> même en l'absence de critère <span class=\"kw-ttt\">biologique</span> strict : <span class=\"kw-ci\">enfant</span>, <span class=\"kw-ci\">femme enceinte</span>, <span class=\"kw-ci\">sujet âgé</span>, <span class=\"kw-ci\">splénectomisé</span>, <span class=\"kw-ci\">immunodéprimé</span>, <span class=\"kw-def\">comorbidité</span> significative.</p>","frequence":1},{"id":"170-8","rang":"A","rubrique":"Prise en charge","titre":"Conditions de prescription d'un traitement curatif d'un accès simple","contenu":"<p>Tous <span class=\"kw-clinique\">les</span> antipaludiques utilisés dans l'accès sont des <span class=\"kw-def\">schizonticides sanguins</span> — seule la <span class=\"kw-ttt\">primaquine</span> agit sur les formes hépatiques quiescentes (<span class=\"kw-def\">hypnozoïtes</span> de <i><span class=\"kw-etio\">P. vivax</span></i> et <i><span class=\"kw-etio\">P. ovale</span></i>) et n'est utilisée que dans la prévention des rechutes, pas dans l'accès. Les antipaludiques sont délivrés sur prescription médicale uniquement, en général au cours des repas (sauf <span class=\"kw-ttt\">arténimol-pipéraquine</span> à <span class=\"kw-alerte\">prendre à jeun</span>).</p>\n        <p><b>1. Accès simple sans <span class=\"kw-clinique\">vomissement</span> (adulte non-<span class=\"kw-ci\">grossesse</span>)</b> :</p>\n        <ul>\n          <li><b><span class=\"kw-chiffre\">1ère intention</span> — <span class=\"kw-ttt\">ACT</span></b> : <span class=\"kw-ttt\">artéméther-luméfantrine</span> (Riamet®) ou <span class=\"kw-ttt\">arténimol-pipéraquine</span> (Eurartesim®) pendant <span class=\"kw-chiffre\">3 jours</span>. <span class=\"kw-bio\">ECG</span> préalable obl<span class=\"kw-chiffre\">iga</span>toire (allongement du QT).</li>\n          <li>Alternatives : <span class=\"kw-ttt\">atovaquone-proguanil</span> (Malarone®) ou <span class=\"kw-ttt\">méfloquine</span> (Lariam®).</li>\n        </ul>\n        <p><b>2. Accès simple avec <span class=\"kw-clinique\">vomissements</span></b> : <span class=\"kw-ttt\">quinine IV</span> en perfusion lente dans du G<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> %</span> (<span class=\"kw-alerte\">jamais en IM — nécrose</span>). Protocole : <b>dose de charge <span class=\"kw-chiffre\">16-17 mg/kg</span> sur <span class=\"kw-chiffre\">4 h</span></b>, puis <span class=\"kw-chiffre\">8 mg/kg toutes les 8 h</span> en perfusion de <span class=\"kw-chiffre\">4 h</span>. Relais per os par <span class=\"kw-ttt\">ACT</span> dès l'arrêt des vomissements. <span class=\"kw-def\">Surveillance</span> <span class=\"kw-bio\">ECG</span> (QT) et <span class=\"kw-bio\">glycémique</span> (risque d'<span class=\"kw-clinique\">hypoglycémie</span> <span class=\"kw-etio\">iatrogène</span>, surtout chez la femme enceinte).</p>\n        <p><b>3. Cas particuliers à connaître</b> :</p>\n        <ul>\n          <li><b>Enfant</b> : <span class=\"kw-alerte\">hospitalisation</span> systématique. <span class=\"kw-ttt\">ACT</span> en <span class=\"kw-chiffre\">1ère intention</span> (<span class=\"kw-chiffre\">3 j</span>), 2ème intention <span class=\"kw-ttt\">atovaquone-proguanil</span> ou <span class=\"kw-ttt\">méfloquine</span>. Comprimés à écraser si <span class=\"kw-chiffre\">&lt; 6 ans</span>. Si <span class=\"kw-clinique\">vomissement</span> après la prise → reprendre la dose ; si persistant → <span class=\"kw-ttt\">quinine IV</span>.</li>\n          <li><b>Femme enceinte au 1er trimestre</b> : <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">quinine</span> (référence) ou <span class=\"kw-ttt\">atovaquone-proguanil</span> à défaut. <span class=\"kw-ci\">ACT contre-indiqué au 1er trimestre</span>.</li>\n          <li><b>Femme enceinte <span class=\"kw-chiffre\">≥ 2</span>ème trimestre</b> : <span class=\"kw-ttt\">artéméther-luméfantrine</span> privilégié.</li>\n        </ul>\n        <p><b>Critères d'éligibilité à un traitement ambulatoire</b> (rares — par défaut on hospitalise au moins <span class=\"kw-chiffre\">24 h</span>) : équipe entraînée, 1ère prise bien tolérée sous <span class=\"kw-def\">surveillance</span>, famille fiable, suivi possible à <span class=\"kw-chiffre\">J3/J7/J28</span>, diagnostic d'espèce fiable, absence d'échec d'un précédent traitement.</p>","frequence":4},{"id":"170-9","rang":"B","rubrique":"Prise en charge","titre":"Principes de surveillance d'un accès simple","contenu":"<p>La <span class=\"kw-def\">surveillance</span> post-traitement de l'<span class=\"kw-clinique\">accès palustre</span> repose sur trois piliers : clinique, <span class=\"kw-ttt\">biologique</span> et parasitologique. <span class=\"kw-clinique\">Les</span> ⭐⭐⭐ de cet objectif (<span class=\"kw-chiffre\">3 QCM EDN</span> tombés) doivent attirer l'attention.</p>\n        <p><b>1. <span class=\"kw-def\">Surveillance</span> parasitologique par <span class=\"kw-bio\">frottis mince + goutte épaisse</span></b> à trois temps fixes :</p>\n        <ul>\n          <li><span class=\"kw-chiffre\">J3</span> — parasitémie doit être <span class=\"kw-chiffre\">&lt; 25 % de la valeur initiale</span>. Si elle reste supérieure → suspecter une résistance ou un défaut d'observance.</li>\n          <li><span class=\"kw-chiffre\">J7</span> — parasitémie doit être négative. <span class=\"kw-alerte\">Une parasitémie résiduelle à J7 = échec thérapeutique</span> → changer de molécule.</li>\n          <li><span class=\"kw-chiffre\">J28</span> — <span class=\"kw-def\">dépistage</span> d'une rechute (résistance, ou <span class=\"kw-def\">hypnozoïte</span> pour <i>vivax/ovale</i>).</li>\n        </ul>\n        <p><b>2. <span class=\"kw-def\">Surveillance</span> clinique</b> — <span class=\"kw-clinique\">apyrexie sous 72 h</span>, disparition des signes digestifs, vigilance sur l'apparition d'un <span class=\"kw-alerte\">signe de gravité</span> (rare une fois le traitement débuté, mais possible si parasitémie initialement élevée).</p>\n        <p><b>3. <span class=\"kw-ci\"><span class=\"kw-def\">Surveillance</span> hématologique</span> hebdomadaire</b> si traitement par <span class=\"kw-ttt\">artésunate IV</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">réticulocytes</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobine</span> à <span class=\"kw-chiffre\">J3, J7, J14, J28</span>. Pourquoi ? <span class=\"kw-alerte\">Anémie hémolytique retardée post-artésunate</span> (<span class=\"kw-def\">incidence</span> ~<span class=\"kw-chiffre\">13 %</span>, mécanisme : lyse synchrone des hématies ayant contenu un parasite tué — « pitting » splénique différé). Ne pas la dépister = piège majeur.</p>\n        <p><b>4. <span class=\"kw-def\">Surveillance</span> biochimique</b> — résolution de la cytolyse et de la <span class=\"kw-clinique\">cholestase</span>, normalisation des <span class=\"kw-bio\">plaquettes</span>, contrôle <span class=\"kw-bio\">CRP</span>. Pas de <span class=\"kw-def\">chimioprophylaxie</span> à reprendre après traitement (sauf nouveau séjour en zone d'endémie).</p>","frequence":3},{"id":"170-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement et les principes de la surveillance d'un accès palustre grave","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Tout accès grave (<span class=\"kw-chiffre\">≥ 1</span> critère <span class=\"kw-def\">OMS</span>, cf. objectif « Identifier un accès grave ») impose l'<span class=\"kw-alerte\">hospitalisation en réanimation</span> et un traitement <span class=\"kw-ttt\">antiparasitaire</span> <span class=\"kw-alerte\">IV débuté sans délai</span>.</div>\n        <p><b>1. Traitement <span class=\"kw-ttt\">antiparasitaire</span></b></p>\n        <ul>\n          <li><b>1ʳᵉ intention — <span class=\"kw-ttt\">artésunate IV</span></b> (traitement de choix des accès graves, <span class=\"kw-def\">ATU</span>) : <span class=\"kw-chiffre\">3 doses minimum</span> à <span class=\"kw-chiffre\">H0, H12, H24</span>, poursuivi <span class=\"kw-chiffre\">&gt; 24 h</span> jusqu'à disparition des <span class=\"kw-alerte\">signes de gravité</span>. Puis <b>relais per os par <span class=\"kw-ttt\">ACT</span></b> dès amélioration clinique et tolérance digestive.</li>\n          <li><b>Recours — <span class=\"kw-ttt\">quinine IV</span></b> si artésunate indisponible ou <span class=\"kw-ci\">contre-indiqué</span> : perfusion lente dans du <span class=\"kw-ttt\">G5 % ou G10 %</span> (<span class=\"kw-alerte\">jamais en IM</span>), <span class=\"kw-chiffre\">sans dose de charge</span> en cas de <span class=\"kw-def\">chimioprophylaxie</span> préalable par quinine/méfloquine.</li>\n        </ul>\n        <p><b>2. Traitements associés des défaillances</b></p>\n        <ul>\n          <li><span class=\"kw-bio\">Hypoglycémie</span> (<span class=\"kw-chiffre\">&lt; 2,2 mmol/L</span>) → <span class=\"kw-ttt\">sérum glucosé 10-30 % IV</span> avec <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">glycémie</span>.</li>\n          <li>Anémie profonde (<span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">&lt; 7 g/dL</span>) → <span class=\"kw-ttt\">transfusion de concentrés globulaires</span>.</li>\n          <li><span class=\"kw-alerte\">Réanimation</span> des défaillances d'organe selon l'atteinte (ventilation, remplissage/catécholamines, épuration extra-rénale).</li>\n        </ul>\n        <p><b>3. <span class=\"kw-def\">Surveillance</span></b></p>\n        <ul>\n          <li><b>Parasitologique</b> : <span class=\"kw-bio\">frottis + goutte épaisse</span> à <span class=\"kw-chiffre\">J3</span> (&lt;<span class=\"kw-chiffre\"> 25 %</span> de <span class=\"kw-chiffre\">J0</span>), <span class=\"kw-chiffre\">J7</span> (négativation) et <span class=\"kw-chiffre\">J28</span>.</li>\n          <li><b>Hématologique post-artésunate</b> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">réticulocytes</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobine</span> à <span class=\"kw-chiffre\">J3, J7, J14, J28</span> — <span class=\"kw-def\">dépistage</span> de l'<span class=\"kw-alerte\">anémie hémolytique retardée post-artésunate</span> (<span class=\"kw-def\">incidence</span> ~<span class=\"kw-chiffre\">13 %</span>, survient entre <span class=\"kw-chiffre\">J7</span> et J28).</li>\n        </ul>","frequence":1},{"id":"170-11","rang":"A","rubrique":"Prévention","titre":"Modalités de la prévention antivectorielle","contenu":"<p>La protection antivectorielle est la <span class=\"kw-alerte\">mesure principale</span> de prévention du <span class=\"kw-clinique\">paludisme</span> — elle agit sur le maillon faible du cycle (la piqûre par l'<span class=\"kw-etio\">anophèle femelle</span>) et complète la <span class=\"kw-def\">chimioprophylaxie</span> (qui n'est jamais <span class=\"kw-chiffre\">100 %</span> efficace).</p>\n<p><b>Quand</b> — strictement <span class=\"kw-alerte\">dès la tombée du jour et pendant toute la nuit</span> (l'<span class=\"kw-etio\">anophèle</span> pique au crépuscule et la nuit, contrairement à <i><span class=\"kw-etio\">Aedes</span></i> qui pique le jour).</p>\n<p><b>Trois outils d'efficacité démontrée</b> :</p>\n<ul>\n  <li><b>Vêtements couvrants</b> — manches longues, pantalons, chaussettes, <b>de préférence de <span class=\"kw-clinique\">couleur claire</span></b> (l'<span class=\"kw-etio\">anophèle</span> est attiré par <span class=\"kw-clinique\">les</span> couleurs sombres) ; éventuellement imprégnés de <span class=\"kw-ttt\">pyréthrinoïdes</span> (perméthrine).</li>\n  <li><b>Répulsifs cutanés</b> appliqués sur <span class=\"kw-clinique\">les</span> zones découvertes — <span class=\"kw-ttt\">DEET</span> (<span class=\"kw-chiffre\">20-50 %</span>), <span class=\"kw-ttt\">citriodiol</span> (<span class=\"kw-chiffre\">20-30 %</span>), <span class=\"kw-ttt\">IR3535</span> (<span class=\"kw-chiffre\">20 %</span>). Réappliquer toutes les <span class=\"kw-chiffre\">4-8 h</span>.</li>\n  <li><b>Moustiquaires imprégnées de <span class=\"kw-ttt\">pyréthrinoïdes</span></b> (perméthrine) — indispensable la nuit dans <span class=\"kw-clinique\">les</span> zones à fort niveau de transmission.</li>\n</ul>\n<p><b>Particularités pédiatriques</b> (à connaître ++ pour l'EDN — l'EDN aime <span class=\"kw-clinique\">les</span> pièges sur les âges et les nombres d'applications) :</p>\n<table >\n  <thead><tr><th>Tranche d'âge</th><th>Molécules autorisées</th><th>Applications/jour max</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-chiffre\">&lt; 6 mois</span></td><td><span class=\"kw-ci\">Aucun répulsif cutané</span> (toxicité encéphalique : immaturité <span class=\"kw-def\">BHE</span>)</td><td>—</td></tr>\n    <tr><td><span class=\"kw-chiffre\">6 – 30 mois</span></td><td><span class=\"kw-ttt\">DEET 10-30 %</span>, <span class=\"kw-ttt\">citriodiol 20-30 %</span>, <span class=\"kw-ttt\">IR3535 20 %</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n    <tr><td><span class=\"kw-chiffre\">30 mois – 12 ans</span></td><td>Idem</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n    <tr><td><span class=\"kw-chiffre\">&gt; 12 ans</span></td><td>Idem (concentrations adulte)</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n  </tbody>\n</table>\n<p><b>Femme enceinte</b> : la prévention antivectorielle est <span class=\"kw-alerte\">prioritaire et renforcée</span> (<span class=\"kw-clinique\">paludisme</span> gravidique plus grave). <span class=\"kw-ttt\">DEET 20-30 %</span>, <span class=\"kw-ttt\">IR3535 20-35 %</span> et <span class=\"kw-ttt\">citriodiol 20-30 %</span> sont autorisés. <span class=\"kw-alerte\">Moustiquaire imprégnée systématique</span>, vêtements couvrants nuit et jour.</p>\n<p>Application sur la plus petite surface de peau découverte non lésée. <span class=\"kw-ci\">Jamais sur lèvres, paupières, doigts (mains à la bouche), zones lésées</span>.</p>","frequence":3},{"id":"170-12","rang":"A","rubrique":"Prévention","titre":"Modalités de la chimioprophylaxie antipalustre","contenu":"<p><span class=\"kw-alerte\">9 QCM EDN sur cet objectif — record absolu de l'item 170.</span> À maîtriser dans le détail (molécules, schémas de prise, <span class=\"kw-ci\">contre-indications</span>, pédiatrie).</p>\n<p>La <span class=\"kw-def\">chimioprophylaxie</span> concerne <b>voyageurs en zone d'endémie + expatriés</b>. Elle est <span class=\"kw-alerte\">toujours associée à la protection antivectorielle</span> — jamais en monothérapie. Elle <span class=\"kw-alerte\">ne protège pas à 100 %</span> (même bien conduite). <span class=\"kw-clinique\">Les</span> recommandations sont publiées chaque année dans le <span class=\"kw-def\">BEH</span> par le <span class=\"kw-def\">HCSP</span>. La chimioprophylaxie n'est <span class=\"kw-alerte\">pas remboursée</span> par la Sécurité sociale.</p>\n<p><b>Trois molécules recommandées en Afrique subsaharienne</b> (le périmètre où l'EDN attend une maîtrise solide) :</p>\n<table >\n  <thead><tr><th>Molécule</th><th>Début</th><th>Fréquence</th><th>Fin (post-retour)</th><th>Pédiatrie</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-ttt\">Atovaquone-proguanil</span> (Malarone®)</td><td>Veille du départ ou durant séjour</td><td>Quotidienne</td><td><span class=\"kw-chiffre\">1 semaine</span> après (agit aussi sur formes hépatiques)</td><td>Dès ≥ <span class=\"kw-chiffre\">11 kg</span></td></tr>\n    <tr><td><span class=\"kw-ttt\">Méfloquine</span> (Lariam®)</td><td><span class=\"kw-chiffre\">10 jours avant</span> le départ (tester tolérance, demi-vie longue)</td><td>Hebdomadaire</td><td><span class=\"kw-chiffre\">3 semaines</span> après</td><td>Dès ≥ <span class=\"kw-chiffre\">15 kg</span></td></tr>\n    <tr><td><span class=\"kw-ttt\">Doxycycline</span></td><td>Durant le séjour</td><td>Quotidienne</td><td><span class=\"kw-chiffre\">4 semaines</span> après</td><td>Dès <span class=\"kw-chiffre\">≥ 8 ans</span></td></tr>\n  </tbody>\n</table>\n<p><b>Chloroquine</b> (Nivaquine®) — <span class=\"kw-alerte\">obsolète en Afrique subsaharienne</span> (résistances généralisées de <i><span class=\"kw-clinique\">P. falciparum</span></i>) et donc <span class=\"kw-alerte\">non recommandée dans la majorité des destinations tropicales</span>. Elle reste cependant indiquée dans quelques zones rares à <i><span class=\"kw-etio\">P. vivax</span></i>/<i><span class=\"kw-etio\">P. ovale</span></i> dominants sans falciparum résistant : Amérique centrale au nord du canal de Panama, Caraïbes hors Haïti et République dominicaine, certaines zones du Moyen-Orient. <span class=\"kw-alerte\">Stratégie générale</span> : la molécule se choisit selon la zone (carte HCSP/BEH annuelle), la durée du séjour, le profil du voyageur (âge, <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-def\">comorbidités</span>) et la tolérance attendue.</p>\n<p><b><span class=\"kw-ci\">Contre-indications</span> clés à mémoriser</b> :</p>\n<ul>\n  <li><span class=\"kw-ttt\">Méfloquine</span> — <span class=\"kw-ci\">ATCD de convulsions ou troubles psychiatriques</span>, <span class=\"kw-ci\">valproate de sodium</span>, <span class=\"kw-ci\">allaitement</span>, déconseillée si plongée sous-marine, <span class=\"kw-ci\">&lt; 5 kg</span>.</li>\n  <li><span class=\"kw-ttt\">Doxycycline</span> — <span class=\"kw-ci\">enfant &lt; 8 ans</span> (effets sur l'émail dentaire et la croissance osseuse) et <span class=\"kw-ci\">grossesse</span>. Phototoxicité ++ → conseiller protection solaire.</li>\n  <li><span class=\"kw-ttt\">Atovaquone-proguanil</span> — peu de <span class=\"kw-ci\">CI absolues</span>, profil bien toléré, souvent privilégiée chez l'adulte non-<span class=\"kw-etio\">allergique</span>.</li>\n</ul>\n<p><b>Effets indésirables à connaître</b> : <span class=\"kw-ttt\">méfloquine</span> → cauchemars, sensations ébrieuses, dépression, <span class=\"kw-clinique\">vertiges</span>, insomnie (« neuro-psy » = bagage à mémoriser ++ pour l'EDN) ; <span class=\"kw-ttt\">doxycycline</span> → phototoxicité, ulcérations œsophagiennes (prendre debout, avec un grand verre d'eau), troubles digestifs.</p>\n<p><b>Logique des durées post-retour</b> : la durée prolongée pour <span class=\"kw-ttt\">méfloquine</span> (<span class=\"kw-chiffre\">3 sem</span>) et <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-chiffre\">4 sem</span>) couvre l'incubation des sporozoïtes et la <span class=\"kw-def\">schizogonie hépatique</span>. L'<span class=\"kw-ttt\">atovaquone-proguanil</span> agit aussi sur <span class=\"kw-clinique\">les</span> formes hépatiques → <span class=\"kw-chiffre\">1 semaine</span> suffit.</p>","frequence":9},{"id":"170-13","rang":"A","rubrique":"Prévention","titre":"Connaître les conditions de déclaration obligatoire","contenu":"<p><span class=\"kw-alerte\">Piège classique EDN</span> que beaucoup ratent : <span class=\"kw-alerte\">seul le paludisme AUTOCHTONE est une maladie à déclaration obligatoire (<span class=\"kw-def\">MDO</span>) en France.</span></p>\n        <p><b>Zones concernées par la <span class=\"kw-def\">DO</span></b> : Guyane française, Mayotte, Réunion, Antilles (Martinique, Guadeloupe). Le <span class=\"kw-clinique\">paludisme</span> autochtone correspond à un cas contracté localement, sans notion de voyage, traduisant une transmission vectorielle sur place.</p>\n        <p><b>Ce qui N'EST PAS une MDO</b> : le <span class=\"kw-alerte\">paludisme d'importation en métropole</span> (≈ <span class=\"kw-chiffre\">4 000 cas/an</span>) — il est <span class=\"kw-def\">suivi</span> par le <span class=\"kw-def\">CNR</span> du <span class=\"kw-clinique\">paludisme</span> (Centre National de Référence) via un réseau de laboratoires sentinelles, mais pas par une déclaration obl<span class=\"kw-chiffre\">iga</span>toire stricto sensu.</p>\n        <p><b>Conséquence pratique</b> : un voyageur revenant d'Afrique avec un <span class=\"kw-clinique\">paludisme</span> à <i><span class=\"kw-etio\">P. falciparum</span></i> diagnostiqué à Nice ne fait <span class=\"kw-alerte\">pas</span> l'objet d'une <span class=\"kw-def\">DO</span> réglementaire — il est simplement déclaré dans <span class=\"kw-clinique\">les</span> bases du <span class=\"kw-def\">CNR</span> par le biologiste.</p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> diagnostique ET thérapeutique :</strong> toute <span class=\"kw-clinique\">fièvre</span> au retour d’une <span class=\"kw-def\">zone d’endémie palustre</span> = <span class=\"kw-alerte\">paludisme jusqu’à preuve du contraire</span>, même sous <span class=\"kw-ttt\">chimioprophylaxie</span> bien conduite et même tardivement.<br><strong>Pourquoi :</strong> un <span class=\"kw-alerte\">accès simple peut évoluer rapidement vers un accès grave</span> ; <span class=\"kw-clinique\">les</span> manifestations sont essentiellement celles d’une <span class=\"kw-clinique\">anémie hémolytique</span>.</p><p><strong>Diagnostic en <span class=\"kw-alerte\">urgence</span> — sans attendre le pic fébrile</strong></p><ul><li><span class=\"kw-bio\">Frottis mince sanguin</span> + <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">TDR</span> (ou <span class=\"kw-bio\">PCR</span> / technique sensible si disponible)</li><li>Résultat rendu par le biologiste en <span class=\"kw-chiffre\">&lt; 2 h</span></li><li><span class=\"kw-bio\">Frottis mince</span> indispensable : <span class=\"kw-def\">diagnostic d’espèce</span> + <span class=\"kw-bio\">parasitémie</span> (<span class=\"kw-def\">suivi</span> de la décroissance)</li></ul><p><strong>Si premier examen négatif mais doute persistant</strong></p><ul><li>réitérer <span class=\"kw-bio\">frottis</span> + <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">TDR</span> à <span class=\"kw-chiffre\">12-24 h</span></li></ul>","hospit":"<p><strong>Règle :</strong> <span class=\"kw-clinique\">les</span> critères autorisant un traitement <span class=\"kw-def\">ambulatoire</span> sont rarement réunis chez l’adulte → <span class=\"kw-alerte\">hospitalisation au moindre doute</span> ; chez l’<span class=\"kw-def\">enfant</span>, <span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-alerte\">systématique</span>.</p><p><strong>Accès grave → <span class=\"kw-alerte\">réanimation</span></strong></p><ul><li>≥ <span class=\"kw-chiffre\">1</span> <span class=\"kw-alerte\">critère de gravité OMS</span> → avis du réanimateur + <span class=\"kw-alerte\">hospitalisation</span> en réanimation</li></ul><p><strong>Critères d’<span class=\"kw-alerte\">hospitalisation</span> (accès simple)</strong></p><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-def\">enfant</span>, <span class=\"kw-def\">femme enceinte</span>, <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-def\">splénectomie</span></li><li><span class=\"kw-clinique\">Vomissements</span> / troubles digestifs compromettant la prise per os</li><li><span class=\"kw-def\">Suivi</span> impossible à <span class=\"kw-chiffre\">J3</span>, <span class=\"kw-chiffre\">J7</span>, <span class=\"kw-chiffre\">J28</span> ; <span class=\"kw-alerte\">échec d’un 1ᵉʳ traitement</span></li><li><span class=\"kw-bio\">Parasitémie</span> <span class=\"kw-chiffre\">&gt; 2 %</span>, <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span>, <span class=\"kw-bio\">anémie</span> <span class=\"kw-chiffre\">&lt; 10 g/dL</span>, <span class=\"kw-bio\">créatininémie</span> <span class=\"kw-chiffre\">&gt; 150 µmol/L</span></li></ul><p><strong>Enfant — <span class=\"kw-alerte\">hospitalisation</span> systématique</strong></p><ul><li><span class=\"kw-def\">UHCD</span> : accès simple <span class=\"kw-clinique\">sans intolérance digestive</span></li><li><span class=\"kw-def\">USC</span> / <span class=\"kw-alerte\">réanimation</span> : accès simple <span class=\"kw-clinique\">avec intolérance digestive</span> (anti-paludique IV)</li><li><span class=\"kw-alerte\">Réanimation</span> : <span class=\"kw-alerte\">accès grave</span></li></ul><p><strong>Traitement ambulatoire (rarement possible)</strong></p><ul><li>tous <span class=\"kw-clinique\">les</span> critères d’<span class=\"kw-alerte\">hospitalisation</span> absents, équipe entraînée, 1ʳᵉ prise bien tolérée, famille fiable, diagnostic fiable</li></ul>","redflags":"<p><strong>Définition :</strong> la présence d’<span class=\"kw-alerte\">au moins UN critère de gravité OMS</span> = <span class=\"kw-alerte\">accès grave</span> = <span class=\"kw-ttt\">artésunate IV</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-alerte\">réanimation</span>.</p><ul><li><strong>Neurologique :</strong> <span class=\"kw-alerte\">coma</span> (<span class=\"kw-chiffre\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 11</span>), <span class=\"kw-alerte\">obnubilation</span>, <span class=\"kw-alerte\">confusion</span>, <span class=\"kw-alerte\">prostration</span>, <span class=\"kw-alerte\">convulsions</span> — <span class=\"kw-clinique\">neuropaludisme</span></li><li><strong>Respiratoire :</strong> <span class=\"kw-alerte\">défaillance respiratoire</span> — <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">&lt; 60 mmHg</span>, <span class=\"kw-clinique\">SpO2</span> <span class=\"kw-chiffre\">&lt; 92 %</span>, <span class=\"kw-clinique\">FR</span> <span class=\"kw-chiffre\">&gt; 30/min</span>, ou <span class=\"kw-bio\">PaO2/FiO2</span> <span class=\"kw-chiffre\">&lt; 300 mmHg</span> si ventilé, images <span class=\"kw-imagerie\">interstitielles/alvéolaires</span></li><li><strong>Cardio-circulatoire :</strong> <span class=\"kw-alerte\">défaillance cardiocirculatoire</span> — <span class=\"kw-clinique\">PAS</span> <span class=\"kw-chiffre\">&lt; 80 mmHg</span>, recours aux <span class=\"kw-ttt\">catécholamines</span>, signes d’<span class=\"kw-alerte\">hypoperfusion périphérique</span></li><li><strong>Hématologique :</strong> <span class=\"kw-alerte\">hémorragie</span>, <span class=\"kw-clinique\">ictère</span> ou <span class=\"kw-bio\">bilirubine totale</span> <span class=\"kw-chiffre\">&gt; 50 µmol/L</span>, <span class=\"kw-alerte\">hémoglobinurie macroscopique</span>, <span class=\"kw-alerte\">anémie profonde</span> (adulte <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">&lt; 7 g/dL</span> ; enfant <span class=\"kw-chiffre\">&lt; 5 g/dL</span>)</li><li><strong>Rénal :</strong> <span class=\"kw-bio\">créatininémie</span> <span class=\"kw-chiffre\">&gt; 265 µmol/L</span> ou <span class=\"kw-bio\">urée</span> <span class=\"kw-chiffre\">&gt; 20 mmol/L</span>, <span class=\"kw-alerte\">oligurie</span> (<span class=\"kw-chiffre\">&lt; 400 mL/24 h</span> malgré réhydratation)</li><li><strong>Métabolique :</strong> <span class=\"kw-alerte\">acidose</span> (<span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">&lt; 7,35</span> ou <span class=\"kw-bio\">HCO3⁻</span> <span class=\"kw-chiffre\">&lt; 15 mmol/L</span>), <span class=\"kw-alerte\">hyperlactatémie</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> (a fortiori <span class=\"kw-chiffre\">&gt; 5</span>)</li><li><strong>Glycémique :</strong> <span class=\"kw-alerte\">hypoglycémie</span> <span class=\"kw-chiffre\">&lt; 2,2 mmol/L</span> (<span class=\"kw-chiffre\">&lt; 0,4 g/L</span>)</li><li><strong>Parasitologique :</strong> <span class=\"kw-bio\">parasitémie</span> élevée — adulte <span class=\"kw-chiffre\">&gt; 4 %</span>, enfant <span class=\"kw-chiffre\">&gt; 10 %</span></li></ul>","principes":"<p><strong>Socle :</strong> tous <span class=\"kw-clinique\">les</span> anti-paludiques de l’accès sont <span class=\"kw-def\">schizonticides sanguins</span> ; seule la <span class=\"kw-ttt\">primaquine</span> agit sur les <span class=\"kw-etio\">formes hépatiques quiescentes</span> de <span class=\"kw-etio\">P. vivax</span> et <span class=\"kw-etio\">P. ovale</span>.<br><strong>Modalités :</strong> délivrance sur prescription médicale, prise au cours des repas (sauf <span class=\"kw-ttt\">arténimol-pipéraquine</span> à jeun).</p><p><strong>Accès simple non compliqué — adulte</strong></p><ul><li>Sans <span class=\"kw-clinique\">vomissement</span> : <span class=\"kw-ttt\">artéméther-luméfantrine</span> ou <span class=\"kw-ttt\">arténimol-pipéraquine</span> (<span class=\"kw-ttt\">ACT</span>, <span class=\"kw-chiffre\">3 jours</span>) en 1ʳᵉ intention</li><li>Avec <span class=\"kw-clinique\">vomissement</span> : <span class=\"kw-ttt\">quinine IV</span> en perfusion lente dans <span class=\"kw-ttt\">G5 %</span>, puis relais par <span class=\"kw-ttt\">ACT</span> dès l’arrêt des <span class=\"kw-clinique\">vomissements</span></li><li><span class=\"kw-ci\">Jamais de quinine en IM</span> (<span class=\"kw-clinique\">nécrose</span> musculaire)</li></ul><p><strong>Accès simple — terrains particuliers</strong></p><ul><li><span class=\"kw-def\">Enfant</span> : <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">ACT</span> <span class=\"kw-chiffre\">3 jours</span> en 1ʳᵉ intention ; <span class=\"kw-ttt\">atovaquone-proguanil</span> ou <span class=\"kw-ttt\">méfloquine</span> en 2ⁿᵈ intention</li><li><span class=\"kw-def\">Femme enceinte</span> : <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">quinine</span> (ou <span class=\"kw-ttt\">atovaquone-proguanil</span> à défaut) ; <span class=\"kw-ttt\">artéméther-luméfantrine</span> privilégié à partir du <span class=\"kw-chiffre\">2ⁿᵈ trimestre</span></li></ul><p><strong><span class=\"kw-clinique\">Paludisme</span> grave (adulte, femme enceinte, enfant)</strong></p><ul><li><span class=\"kw-ttt\">Artésunate IV</span> en <span class=\"kw-alerte\">urgence</span> pendant <span class=\"kw-chiffre\">&gt; 24 h</span> (<span class=\"kw-chiffre\">3 doses : H0, H12, H24</span>) ou jusqu’à disparition des <span class=\"kw-alerte\">signes de gravité</span> — <span class=\"kw-def\">ATU nominative</span> (pas d’AMM en France)</li><li>Si <span class=\"kw-ttt\">artésunate</span> indisponible : <span class=\"kw-ttt\">quinine IV</span> dans <span class=\"kw-ttt\">G5 %</span> ou <span class=\"kw-ttt\">G10 %</span></li><li><span class=\"kw-bio\">Surveillance ECG</span> et <span class=\"kw-bio\">glycémique</span> jusqu’à disparition des <span class=\"kw-alerte\">signes de gravité</span> et de la parasitémie</li><li>Poursuite IV selon l’état clinico-<span class=\"kw-ttt\">biologique</span> (en moyenne <span class=\"kw-chiffre\">48 h</span>, maximum <span class=\"kw-chiffre\">7 jours</span>)</li><li>Relais per os par une <span class=\"kw-ttt\">ACT</span> pendant <span class=\"kw-chiffre\">3 jours</span> chez le patient conscient, sans <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span>, à transit fonctionnel</li></ul><p><strong>Mesures associées de l’accès grave</strong></p><ul><li><span class=\"kw-alerte\">Hypoglycémie</span> majeure : <span class=\"kw-ttt\">glucosé 10-30 %</span> IV + <span class=\"kw-def\">surveillance</span> glycémique</li><li><span class=\"kw-alerte\">Anémie profonde</span> (<span class=\"kw-chiffre\">&lt; 7 g/dL</span>) : <span class=\"kw-ttt\">transfusion de concentrés globulaires</span></li><li><span class=\"kw-ttt\">Oxygénothérapie</span> ± <span class=\"kw-ttt\">assistance ventilatoire</span> ± <span class=\"kw-ttt\">épuration extra-rénale</span></li><li>Surveiller l’<span class=\"kw-bio\">hypophosphatémie</span> (phosphore consommé par le parasite)</li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> à connaître</strong></p><ul><li><span class=\"kw-ttt\">Méfloquine</span> : <span class=\"kw-ci\">enfant &lt; 5 kg</span>, <span class=\"kw-ci\">allaitement</span>, <span class=\"kw-ci\">antécédents de convulsions ou troubles psychiatriques</span>, <span class=\"kw-ci\">valproate de sodium</span></li><li><span class=\"kw-ttt\">Doxycycline</span> : <span class=\"kw-ci\">enfant &lt; 8 ans</span>, <span class=\"kw-ci\">grossesse</span></li><li><span class=\"kw-ttt\">ACT</span> : <span class=\"kw-ci\">1ᵉʳ trimestre de grossesse</span>, allongement du <span class=\"kw-clinique\">QT</span> (<span class=\"kw-imagerie\">ECG</span> préalable)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> parasitologique :</strong> <span class=\"kw-bio\">frottis</span> + <span class=\"kw-bio\">goutte épaisse</span> à <span class=\"kw-chiffre\">J3</span> (<span class=\"kw-bio\">parasitémie</span> <span class=\"kw-chiffre\">&lt; 25 %</span> de la valeur initiale), <span class=\"kw-chiffre\">J7</span> (négativation) et <span class=\"kw-chiffre\">J28</span> (recherche de rechute / résistance).</p><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">clinique</span> (température, troubles digestifs), <span class=\"kw-bio\">hématologique</span> et <span class=\"kw-bio\">biochimique</span></li><li>Si <span class=\"kw-ttt\">artésunate</span> : <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">hématologique hebdomadaire</span> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">réticulocytes</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobine</span>) à <span class=\"kw-chiffre\">J3, J7, J14, J28</span> — <span class=\"kw-alerte\">anémie hémolytique retardée</span> (jusqu’à <span class=\"kw-chiffre\">1 mois</span>)</li><li>Accès grave : <span class=\"kw-bio\">surveillance ECG</span> et <span class=\"kw-bio\">glycémique</span> jusqu’à disparition des <span class=\"kw-alerte\">signes de gravité</span> et de la parasitémie</li><li><span class=\"kw-def\">Déclaration obligatoire</span> du <span class=\"kw-clinique\">paludisme</span> <span class=\"kw-etio\">autochtone</span> (France, Réunion, Antilles) ; le paludisme d’importation n’est <strong>pas</strong> une MDO</li><li>Pas de reprise de <span class=\"kw-ttt\">chimioprophylaxie</span> après traitement, sauf nouveau séjour en <span class=\"kw-def\">zone d’endémie</span></li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-170-copyright.pdf","label":"Collège Pilly — Paludisme (item 170, PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/50.%20Paludisme%20grave.pdf","label":"Collège CE-MIR — Paludisme grave (PDF)"}],"cards":[{"i":"104c2cc9f6e7","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les critères rénaux de gravité de l'OMS pour le paludisme grave ?","a":"<ul><li>Créatininémie > <strong>265 µmol/L</strong></li><li>Urée > <strong>20 mmol/L</strong></li><li>Diurèse < <strong>400 mL/24h</strong> malgré réhydratation</li></ul>"},{"i":"10b56a6c6124","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quelle est la définition du paludisme grave selon l'OMS ?","a":"<p>Le paludisme grave est défini par la présence d'au moins un <strong>critère clinique ou biologique de gravité OMS</strong> chez un patient infecté par <em>Plasmodium</em>.</p>"},{"i":"5dc24ca9d390","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Pourquoi le paludisme grave est-il considéré comme une urgence absolue ?","a":"<p>C'est une urgence absolue car la <strong>mortalité atteint 10-20 %</strong> même avec un traitement optimal. Le pronostic est étroitement lié au <strong>délai de prise en charge</strong>.</p>"},{"i":"7e284030cb5e","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les critères hématologiques de gravité de l'OMS pour le paludisme grave ?","a":"<ul><li>Hémoglobine (Hb) adulte < <strong>7 g/dL</strong> ou enfant < <strong>5 g/dL</strong></li><li><strong>Hémorragie clinique</strong> (extériorisée ou viscérale)</li><li>Ictère avec bilirubine > <strong>50 µmol/L</strong></li><li><strong>Hémoglobinurie macroscopique</strong></li></ul>"},{"i":"89ed18187688","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les Plasmodium le plus souvent impliqués dans le paludisme grave ?","a":"<p>Le paludisme grave est quasi-exclusivement dû à <em><strong>Plasmodium falciparum</strong></em>. Plus rarement, <em>P. knowlesi</em> ou <em>P. vivax</em> peuvent être en cause.</p>"},{"i":"98023115bf7f","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les critères métaboliques et parasitaires de gravité de l'OMS pour le paludisme grave ?","a":"<ul><li><strong>Acidose</strong> (pH < <strong>7,35</strong> ou bicarbonates < <strong>15 mmol/L</strong>)</li><li><strong>Lactates</strong> > <strong>2 mmol/L</strong></li><li><strong>Hypoglycémie</strong> < <strong>2,2 mmol/L</strong></li><li><strong>Parasitémie</strong> adulte > <strong>4 %</strong> ou enfant > <strong>10 %</strong></li></ul>"},{"i":"9c2d9ebd63c4","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les critères neurologiques de gravité de l'OMS pour le paludisme grave ?","a":"<ul><li>Score de Glasgow < <strong>11</strong></li><li><strong>Convulsions</strong></li><li><strong>Prostration</strong></li></ul>"},{"i":"df8a08546cd7","n":170,"o":"170-1","u":"Définitions","t":"Définition d'un paludisme grave","q":"Quels sont les critères circulatoires de gravité de l'OMS pour le paludisme grave ?","a":"<ul><li>Pression Artérielle Systolique (PAS) < <strong>80 mmHg</strong></li><li>Recours aux <strong>catécholamines</strong></li><li>Signes d'<strong>hypoperfusion</strong></li></ul>"},{"i":"58bf4d62c5da","n":170,"o":"170-11","u":"Prévention","t":"Modalités de la prévention antivectorielle","q":"Quelles sont les recommandations spécifiques de prévention antivectorielle du paludisme chez la femme enceinte ?","a":"<p>La prévention antivectorielle est <strong>prioritaire et renforcée</strong> chez la femme enceinte en raison de la gravité accrue du paludisme gravidique. Il est recommandé :</p><ul><li>L'utilisation de <strong>DEET 20-30%</strong>, <strong>IR3535 20-35%</strong> et <strong>citriodiol 20-30%</strong>.</li><li>Une <strong>moustiquaire imprégnée systématique</strong>.</li><li>Le port de <strong>vêtements couvrants nuit et jour</strong>.</li></ul><p>L'application doit se faire sur la <strong>plus petite surface de peau découverte non lésée</strong>, et <strong>jamais sur les lèvres, paupières, doigts</strong> (risque d'ingestion), ou les zones lésées.</p>"},{"i":"81fff43ac4b8","n":170,"o":"170-11","u":"Prévention","t":"Modalités de la prévention antivectorielle","q":"Quelles sont les particularités concernant l'utilisation des répulsifs cutanés pour la prévention antivectorielle du paludisme chez l'enfant ?","a":"<ul><li><strong>Moins de 6 mois</strong> : <strong>aucun répulsif cutané n'est autorisé</strong> en raison d'une toxicité encéphalique due à l'immaturité de la barrière hémato-encéphalique (BHE).</li><li><strong>De 6 à 30 mois</strong> : <strong>DEET 10-30%</strong>, citriodiol 20-30% ou IR3535 20%, avec <strong>1 application par jour maximum</strong>.</li><li><strong>De 30 mois à 12 ans</strong> : les mêmes molécules et concentrations que précédemment, avec <strong>2 applications par jour maximum</strong>.</li><li><strong>Plus de 12 ans</strong> : les mêmes molécules et concentrations que l'adulte, avec <strong>3 applications par jour maximum</strong>.</li></ul>"},{"i":"c2126fb10aea","n":170,"o":"170-11","u":"Prévention","t":"Modalités de la prévention antivectorielle","q":"Quelle est l'importance de la protection antivectorielle dans la prévention du paludisme ?","a":"<p>La protection antivectorielle est la <strong>mesure principale</strong> de prévention du paludisme, car elle agit sur le <strong>maillon faible du cycle</strong> (la piqûre par l'anophèle femelle) et complète la chimioprophylaxie.</p>"},{"i":"d7ebcedefb71","n":170,"o":"170-11","u":"Prévention","t":"Modalités de la prévention antivectorielle","q":"Quels sont les trois principaux outils d'efficacité démontrée pour la prévention antivectorielle du paludisme chez l'adulte ?","a":"<ul><li>Les <strong>vêtements couvrants</strong> (manches longues, pantalons, chaussettes), de préférence de couleur claire, éventuellement imprégnés de <strong>pyréthrinoïdes (perméthrine)</strong>.</li><li>Les <strong>répulsifs cutanés</strong> appliqués sur les zones découvertes : <strong>DEET (20-50%)</strong>, <strong>citriodiol (20-30%)</strong>, <strong>IR3535 (20%)</strong>. Ils doivent être réappliqués toutes les <strong>4-8 heures</strong>.</li><li>Les <strong>moustiquaires imprégnées de pyréthrinoïdes (perméthrine)</strong>, indispensables la nuit dans les zones à fort niveau de transmission.</li></ul>"},{"i":"1234c8ad213c","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"Quelle est la raison des durées variables de chimioprophylaxie antipalustre après le retour (1 semaine pour atovaquone-proguanil, 3 semaines pour méfloquine, 4 semaines pour doxycycline) ?","a":"<p>La durée prolongée de <strong>3 semaines pour la méfloquine</strong> et de <strong>4 semaines pour la doxycycline</strong> post-retour couvre la totalité de la période d'incubation des sporozoïtes et de la schizogonie hépatique.</p><p>L'<strong>atovaquone-proguanil</strong> agit déjà sur les formes hépatiques, ce qui explique qu'<strong>1 semaine</strong> après le retour soit suffisante.</p>"},{"i":"85a5decd2e84","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"Quel est le schéma de prise (début, fréquence, fin post-retour) de la doxycycline pour la chimioprophylaxie antipalustre, et quelles sont ses contre-indications principales et effets indésirables à prévenir ?","a":"<ul><li><strong>Début :</strong> Durant le séjour.</li><li><strong>Fréquence :</strong> Quotidienne.</li><li><strong>Fin (post-retour) :</strong> <strong>4 semaines</strong> après.</li></ul><p>Les contre-indications principales de la doxycycline sont :</p><ul><li>Enfant <strong>< 8 ans</strong> (en raison des effets sur l'émail dentaire et la croissance osseuse).</li><li><strong>Grossesse</strong>.</li></ul><p>Les effets indésirables à prévenir sont la <strong>phototoxicité</strong> (nécessitant une protection solaire) et les <strong>ulcérations œsophagiennes</strong> (pour lesquelles il faut conseiller une prise en position debout avec un grand verre d'eau).</p>"},{"i":"89bf4afcb965","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"La chloroquine est-elle recommandée pour la chimioprophylaxie antipalustre en Afrique subsaharienne et pourquoi ?","a":"<p>Non, la chloroquine (Nivaquine®) est <strong>obsolète en Afrique subsaharienne</strong> et dans la majorité des destinations tropicales car il existe des <strong>résistances généralisées de <em>P. falciparum</em></strong>.</p>"},{"i":"8a667bd1aaa3","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"Quel est le schéma de prise (début, fréquence, fin post-retour) de la méfloquine (Lariam®) pour la chimioprophylaxie antipalustre, et quelles sont ses contre-indications et effets indésirables neuropsychiques majeurs ?","a":"<ul><li><strong>Début :</strong> <strong>10 jours</strong> avant le départ (pour tester la tolérance en raison de sa longue demi-vie).</li><li><strong>Fréquence :</strong> Hebdomadaire.</li><li><strong>Fin (post-retour) :</strong> <strong>3 semaines</strong> après.</li></ul><p>Les contre-indications clés de la méfloquine sont :</p><ul><li>Antécédents de <strong>convulsions</strong> ou de <strong>troubles psychiatriques</strong>.</li><li>Prise de <strong>valproate de sodium</strong>.</li><li><strong>Allaitement</strong>.</li><li>Déconseillée en cas de <strong>plongée sous-marine</strong>.</li><li>Enfant de <strong>< 5 kg</strong>.</li></ul><p>Ses effets indésirables neuropsychiques à connaître sont : <strong>cauchemars</strong>, <strong>sensations ébrieuses</strong>, <strong>dépression</strong>, <strong>vertiges</strong>, <strong>insomnie</strong>.</p>"},{"i":"a3886e2c8881","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"Quelles sont les trois molécules de chimioprophylaxie antipalustre recommandées en Afrique subsaharienne selon les recommandations françaises, et quels éléments influencent le choix de la molécule ?","a":"<p>Les trois molécules recommandées en Afrique subsaharienne sont :</p><ul><li><strong>Atovaquone-proguanil</strong> (Malarone®)</li><li><strong>Méfloquine</strong> (Lariam®)</li><li><strong>Doxycycline</strong></li></ul><p>Le choix de la molécule dépend :</p><ul><li>De la <strong>zone géographique</strong> (carte HCSP/BEH annuelle).</li><li>De la <strong>durée du séjour</strong>.</li><li>Du <strong>profil du voyageur</strong> (âge, grossesse, comorbidités).</li><li>De la <strong>tolérance</strong> attendue.</p>"},{"i":"ba091f67b6f0","n":170,"o":"170-12","u":"Prévention","t":"Modalités de la chimioprophylaxie antipalustre","q":"Quel est le schéma de prise (début, fréquence, fin post-retour) de l'atovaquone-proguanil (Malarone®) pour la chimioprophylaxie antipalustre, et à partir de quel poids peut-il être utilisé en pédiatrie ?","a":"<ul><li><strong>Début :</strong> Veille du départ ou durant le séjour.</li><li><strong>Fréquence :</strong> Quotidienne.</li><li><strong>Fin (post-retour) :</strong> <strong>1 semaine</strong> après (agit aussi sur les formes hépatiques).</li><li><strong>Pédiatrie :</strong> Dès <strong>≥ 11 kg</strong>.</li></ul>"},{"i":"0c20cd32cbc4","n":170,"o":"170-13","u":"Prévention","t":"Connaître les conditions de déclaration obligatoire","q":"Quelle est la définition d'un cas de paludisme autochtone en France ?","a":"<p>Un cas de paludisme autochtone correspond à un cas <strong>contracté localement</strong>, c'est-à-dire sans notion de voyage, et traduisant une <strong>transmission vectorielle sur place</strong>.</p>"},{"i":"5e65d8a32638","n":170,"o":"170-13","u":"Prévention","t":"Connaître les conditions de déclaration obligatoire","q":"Dans quelles zones géographiques en France le paludisme autochtone est-il une maladie à déclaration obligatoire ?","a":"<p>Le paludisme autochtone est une MDO dans les zones suivantes :</p><ul><li><strong>Guyane française</strong></li><li><strong>Mayotte</strong></li><li><strong>La Réunion</strong></li><li><strong>Antilles</strong> (Martinique, Guadeloupe)</li></ul>"},{"i":"6ea85061caf9","n":170,"o":"170-13","u":"Prévention","t":"Connaître les conditions de déclaration obligatoire","q":"Le paludisme d'importation en métropole est-il une maladie à déclaration obligatoire en France ?","a":"<p>Non, le paludisme d'importation en métropole <strong>n'est pas</strong> une maladie à déclaration obligatoire (MDO) au sens réglementaire. Il est suivi par le Centre National de Référence (CNR) du paludisme via un réseau de laboratoires sentinelles.</p>"},{"i":"da8c1de1b4c3","n":170,"o":"170-13","u":"Prévention","t":"Connaître les conditions de déclaration obligatoire","q":"Quelle est la particularité de la déclaration obligatoire du paludisme en France ?","a":"<p>En France, seul le paludisme <strong>autochtone</strong> est une maladie à déclaration obligatoire (MDO).</p>"},{"i":"2f7e6e304dc7","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Quelle est la principale caractéristique clinique et la gravité associée à <i>Plasmodium falciparum</i> ?","a":"<p>La principale caractéristique de <em>Plasmodium falciparum</em> est sa gravité. C'est la <strong>seule espèce qui tue</strong>, responsable de la quasi-totalité des accès graves de paludisme. Elle ne cause <strong>pas de rechute tardive</strong> car elle ne forme pas d'hypnozoïtes. L'incubation est de <strong>7 jours à 2 mois</strong>.</p>"},{"i":"3cdec6f701f2","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Quelles sont les cinq espèces de Plasmodium pathogènes pour l'Homme et leur principale zone d'endémie ?","a":"<p>Les cinq espèces de Plasmodium pathogènes pour l'Homme sont :</p><ul><li><strong><em>Plasmodium falciparum</em></strong> : Afrique subsaharienne.</li><li><strong><em>Plasmodium vivax</em></strong> : Asie, Amérique latine, Corne de l'Afrique.</li><li><strong><em>Plasmodium ovale</em></strong> : Afrique de l'Ouest, Asie du Sud-Est.</li><li><strong><em>Plasmodium malariae</em></strong> : Afrique, Asie, Amérique du Sud.</li><li><strong><em>Plasmodium knowlesi</em></strong> : Asie du Sud-Est (Bornéo, Malaisie).</li></ul>"},{"i":"4c3e18fa3c67","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Citez deux facteurs génétiques de résistance expliquant la distribution géographique des espèces de Plasmodium.","a":"<p>Deux facteurs génétiques de résistance sont :</p><ul><li>La <strong>drépanocytose hétérozygote (A/S)</strong> : confère une <strong>protection partielle</strong> contre les formes graves de <em>P. falciparum</em>, expliquant sa prévalence en Afrique subsaharienne.</li><li>Le <strong>phénotype Duffy négatif Fy(a-b-)</strong> : confère une <strong>résistance quasi-totale</strong> à l'invasion par <em>P. vivax</em>, ce qui explique la rareté de <em>P. vivax</em> en Afrique de l'Ouest malgré une forte endémie de <em>P. falciparum</em> dans cette zone.</li></ul>"},{"i":"5544ba21de7e","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Pourquoi <i>Plasmodium knowlesi</i> représente-t-il un piège diagnostic et quelle est sa principale caractéristique de gravité ?","a":"<p><strong><em>Plasmodium knowlesi</em></strong> représente un piège diagnostique car son aspect au frottis sanguin est similaire à celui de <em>Plasmodium malariae</em>. Cependant, il peut entraîner une infection <strong>grave</strong> en raison de <strong>parasitémies explosives</strong> et de son <strong>cycle érythrocytaire court (24 heures)</strong>. Il doit être évoqué chez tout voyageur revenant <strong>d'Asie du Sud-Est</strong>.</p>"},{"i":"b10964bdb05a","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Quelle espèce de Plasmodium est caractérisée par une très longue incubation et un tropisme rénal particulier ?","a":"<p><strong><em>Plasmodium malariae</em></strong> est caractérisée par une <strong>très longue incubation</strong>, pouvant aller <strong>jusqu'à plus de 10 ans</strong>. Son tropisme rénal se manifeste par la possibilité de développer un <strong>syndrome néphrotique chronique</strong>.</p>"},{"i":"f0ee49070568","n":170,"o":"170-2","u":"Étiologie","t":"Connaître les principales espèces de Plasmodium","q":"Quelles sont les espèces de Plasmodium associées à un risque de rechute tardive et pourquoi ?","a":"<p>Les espèces de Plasmodium associées à un risque de rechute tardive sont <strong><em>Plasmodium vivax</em> et <em>Plasmodium ovale</em></strong>. Cette particularité est due à leur capacité à former des <strong>hypnozoïtes hépatiques</strong>, des formes latentes qui peuvent réactiver l'infection jusqu'à 3 ans après la primo-infection. Pour les éradiquer, un traitement par <strong>primaquine</strong> est nécessaire (pour <em>P. vivax</em> notamment).</p>"},{"i":"0ead13a1b719","n":170,"o":"170-4","u":"Épidémiologie","t":"Connaître l'épidémiologie du paludisme","q":"Quelle est la situation épidémiologique du paludisme en France et quelles sont les populations à risque ?","a":"<p>En France, le paludisme est <strong>quasi-exclusivement un paludisme d'importation</strong>, avec environ <strong>4 000 cas diagnostiqués par an</strong>. Plus de <strong>85 %</strong> de ces cas proviennent d'<strong>Afrique subsaharienne francophone</strong> et sont à <strong>P. falciparum</strong> dans environ <strong>90 % des cas</strong>. On déplore <strong>10 à 20 décès par an</strong>. Les populations les plus touchées sont les <strong>voyageurs migrants visitant leur famille (VFR)</strong> et les <strong>nouveaux arrivants</strong>.</p>"},{"i":"14a2814e3faf","n":170,"o":"170-4","u":"Épidémiologie","t":"Connaître l'épidémiologie du paludisme","q":"Où sont situées les principales régions d'endémie palustre dans le monde ?","a":"<p>L'endémie palustre est présente dans <strong>plus de 80 pays intertropicaux</strong>. Les principales régions sont :</p><ul><li>l'<strong>Afrique subsaharienne</strong> (90% des décès mondiaux) ;</li><li>l'Asie du Sud-Est ;</li><li>l'Amérique du Sud ;</li><li>les Caraïbes ;</li><li>l'Océanie.</li></ul>"},{"i":"452bd4a7eab2","n":170,"o":"170-4","u":"Épidémiologie","t":"Connaître l'épidémiologie du paludisme","q":"Le paludisme est-il une maladie à déclaration obligatoire (MDO) en France ?","a":"<p>La déclaration obligatoire ne concerne que les <strong>cas autochtones</strong> de paludisme, rencontrés notamment en <strong>Guyane, à Mayotte, à La Réunion et aux Antilles</strong>. Le paludisme d'importation en métropole n'est <strong>PAS une Maladie à Déclaration Obligatoire</strong>.</p>"},{"i":"8a1d38161ca1","n":170,"o":"170-4","u":"Épidémiologie","t":"Connaître l'épidémiologie du paludisme","q":"Quelle est l'ampleur mondiale de la mortalité liée au paludisme et quelle population est la plus touchée ?","a":"<p>Le paludisme est la <strong>1ère cause de décès parasitaire</strong> dans le monde, avec environ <strong>600 000 morts par an</strong> selon l'OMS. <strong>94 %</strong> de ces décès surviennent en <strong>Afrique subsaharienne</strong>, principalement chez l'<strong>enfant de moins de 5 ans</strong>.</p>"},{"i":"16962e9367af","n":170,"o":"170-5","u":"Diagnostic positif","t":"Identifier les circonstances qui imposent la recherche d'un paludisme","q":"Un patient ayant correctement pris une chimioprophylaxie antipaludique est-il exempt de risque de développer un paludisme et faut-il le rechercher en cas de fièvre ?","a":"<p>Non, une chimioprophylaxie correctement prise <strong>n'élimine pas le risque à 100 %</strong>. La suspicion de paludisme doit donc rester intacte et la recherche du parasite est impérative en cas de fièvre.</p>"},{"i":"3989af9aac77","n":170,"o":"170-5","u":"Diagnostic positif","t":"Identifier les circonstances qui imposent la recherche d'un paludisme","q":"Quels sont les délais d'incubation à considérer pour la recherche d'un paludisme en fonction des espèces et de l'ancienneté du séjour en zone d'endémie ?","a":"<ul><li><strong><em>P. falciparum</em></strong> : incubation minimale de <strong>7 jours</strong>, maximale de <strong>2 mois</strong> (dans 95 % des cas).</li><li>Autres espèces (<em>P. vivax</em>, <em>P. ovale</em>) : incubation minimale de <strong>10-15 jours</strong>, maximale allant jusqu'à <strong>3 ans</strong> (en raison des hypnozoïtes).</li><li><em>P. malariae</em> : incubation maximale pouvant aller jusqu'à <strong>plus de 10 ans</strong>.</li></ul><p>Ainsi, un séjour en zone d'endémie palustre, même ancien (par exemple, 6 mois auparavant), ne permet pas d'éliminer le diagnostic de paludisme.</p>"},{"i":"b6c382bbc45c","n":170,"o":"170-5","u":"Diagnostic positif","t":"Identifier les circonstances qui imposent la recherche d'un paludisme","q":"Quels sont les signes cliniques et biologiques évocateurs d'un paludisme à rechercher en cas de suspicion ?","a":"<ul><li><strong>Signes cliniques</strong> : <strong>fièvre</strong> (90 % des cas) avec frissons et sueurs, accès intermittents, syndrome pseudo-grippal (céphalées, myalgies, nausées/vomissements, diarrhée), <strong>splénomégalie inconstante</strong>, <strong>ictère</strong>.</li><li><strong>Signes biologiques</strong> : <strong>thrombopénie quasi-constante</strong> (signe d'alerte important), anémie hémolytique (avec augmentation des LDH, diminution de l'haptoglobine, augmentation de la bilirubine libre), CRP souvent supérieure à 100 mg/L, cytolyse hépatique modérée à prédominance ALAT, leucopénie fréquente, absence d'hyperéosinophilie (signe négatif utile), anémie initialement arégénérative.</li></ul>"},{"i":"dd3ebcaad4c2","n":170,"o":"170-5","u":"Diagnostic positif","t":"Identifier les circonstances qui imposent la recherche d'un paludisme","q":"Quelle est la principale circonstance qui doit alerter le clinicien quant à la possibilité d'un paludisme chez un patient fébrile ?","a":"<p>La principale circonstance est la présence d'une <strong>fièvre inexpliquée au décours d'un séjour en zone d'endémie palustre</strong>. Cette évocation doit subsister même si un autre foyer infectieux est identifié, car les co-infections sont fréquentes et ne masquent pas un paludisme concomitant.</p>"},{"i":"26a66b8944b3","n":170,"o":"170-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un accès palustre (adulte et enfant)","q":"Quels examens complémentaires sont nécessaires pour évaluer la gravité d'un accès palustre ?","a":"<p>Pour évaluer la gravité du paludisme, il faut prélever :</p><ul><li>Une <strong>NFS</strong>.</li><li>Un <strong>bilan d'hémolyse</strong> (LDH, haptoglobine, bilirubine).</li><li>Un <strong>ionogramme</strong>.</li><li><strong>Urée/créatinine</strong>.</li><li>Une <strong>glycémie</strong>.</li><li>Un <strong>bilan hépatique complet</strong>.</li><li>Des <strong>gaz du sang artériels</strong> avec lactates.</li><li>Des <strong>hémocultures aérobies/anaérobies</strong> pour rechercher une co-infection bactérienne fréquente.</li></ul>"},{"i":"37fa7091b560","n":170,"o":"170-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un accès palustre (adulte et enfant)","q":"Quels sont les avantages et inconvénients des principales techniques de diagnostic du paludisme ?","a":"<ul><li>La <strong>goutte épaisse</strong> est très sensible (grand volume de sang lysé) mais ne permet ni le diagnostic d'espèce, ni le suivi, ni la parasitémie.</li><li>Le <strong>frottis mince</strong> est moins sensible mais essentielle pour l'évaluation de la parasitémie (grade de gravité), le diagnostic d'espèce et le suivi.</li><li>Les <strong>TDR</strong> (détection de HRP-2, pLDH) sont spécifiques mais dépendent de la parasitémie (faux négatifs si faible) et ne sont pas utiles pour le suivi (HRP-2 reste + 2-6 semaines).</li><li>La <strong>PCR</strong> est très sensible et permet le diagnostic d'espèce mais reste positive longtemps (jusqu'à 1 mois) ce qui la rend impropre au suivi d'efficacité.</li></ul>"},{"i":"42381f676dc6","n":170,"o":"170-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un accès palustre (adulte et enfant)","q":"Quelle est la stratégie diagnostique recommandée en pratique devant une suspicion de paludisme ?","a":"<p>La stratégie diagnostique repose sur l'association d'une <strong>technique sensible</strong> (goutte épaisse ou PCR rapide) et d'un <strong>frottis mince sanguin</strong>. Si une technique sensible n'est pas disponible, il faut coupler un <strong>TDR (tests de diagnostic rapide)</strong> et un <strong>frottis mince</strong>.</p>"},{"i":"7285870ba668","n":170,"o":"170-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un accès palustre (adulte et enfant)","q":"Quelle est l'urgence diagnostique du paludisme et le délai attendu pour le biologiste ?","a":"<p>Le diagnostic du paludisme est une <strong>urgence biologique absolue</strong>. Le biologiste doit rendre un résultat en <strong>moins de 2 heures</strong> à partir du prélèvement, qui est réalisé sur tube <strong>EDTA</strong> sans attendre de pic fébrile.</p>"},{"i":"92b5a2ee17b0","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Quels sont les critères métaboliques et de parasitémie de gravité de l'OMS pour le paludisme chez l'adulte ?","a":"<p>Critères métaboliques :</p><ul><li>Acidose (<strong>pH &lt; 7,35</strong> ou <strong>HCO₃⁻ &lt; 15 mmol/L</strong>)</li><li>Lactates &gt; <strong>2 mmol/L</strong> (a fortiori &gt; 5)</li><li>Hypoglycémie &lt; <strong>2,2 mmol/L</strong></li></ul><p>Critères de parasitémie :</p><ul><li>Adulte : &gt; <strong>4 %</strong></li></ul>"},{"i":"c2afebfe337a","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Quels sont les critères neurologiques de gravité de l'OMS pour le paludisme ?","a":"<ul><li><strong>Glasgow &lt; 11</strong></li><li>Obnubilation</li><li>Confusion</li><li>Convulsions</li><li>Prostration</li></ul>"},{"i":"e84208d0ced4","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Quels sont les critères justifiant une hospitalisation (sans réanimation) en cas de paludisme ?","a":"<ul><li>Plaquettes &lt; <strong>50 G/L</strong></li><li>Hb &lt; <strong>10 g/dL</strong></li><li>Créatininémie &gt; <strong>150 µmol/L</strong></li><li>Parasitémie &gt; <strong>2 %</strong></li></ul>"},{"i":"f65d3227655e","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Quel est l'impact d'un terrain à risque sur la décision d'hospitalisation face à un paludisme ?","a":"<p>Un terrain à risque impose l'hospitalisation même en l'absence de critère biologique strict. Les terrains à risque incluent :</p><ul><li>Enfant</li><li>Femme enceinte</li><li>Sujet âgé</li><li>Sujet splénectomisé</li><li>Sujet immunodéprimé</li><li>Patient avec comorbidité significative</li></ul>"},{"i":"f79f87202d1a","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Quels sont les critères hématologiques et rénaux de gravité de l'OMS pour le paludisme chez l'adulte ?","a":"<p>Critères hématologiques :</p><ul><li>Hémorragie clinique (extériorisée ou viscérale)</li><li>Ictère ou bilirubinémie &gt; <strong>50 µmol/L</strong></li><li>Hémoglobinurie macroscopique</li><li>Anémie profonde : <strong>Hb &lt; 7 g/dL</strong> ou Ht &lt; 20 %</li></ul><p>Critères rénaux :</p><ul><li>Créatininémie &gt; <strong>265 µmol/L</strong></li><li>Urée &gt; <strong>20 mmol/L</strong></li><li>Diurèse &lt; <strong>400 mL/24h malgré réhydratation</strong></li></ul>"},{"i":"fea6d6c16e18","n":170,"o":"170-7","u":"Diagnostic positif","t":"Identifier un accès grave","q":"Dans le cadre du paludisme, quelle est la démarche systématique à adopter chez tout patient avec un paludisme confirmé, concernant la gravité ?","a":"<p>L'évaluation <strong>clinico-biologique de gravité</strong> est systématique chez tout patient avec un paludisme confirmé, et ce, <strong>indépendamment de l'apparente « bonne tolérance »</strong>. Tout paludisme à <em>P. falciparum</em> doit être considéré comme potentiellement grave jusqu'à preuve du contraire.</p>"},{"i":"25bc02ede2ee","n":170,"o":"170-8","u":"Prise en charge","t":"Conditions de prescription d'un traitement curatif d'un accès simple","q":"Comment prend-on en charge un accès palustre simple avec vomissements ?","a":"<p>En cas de vomissements, le traitement est la <strong>quinine par voie intraveineuse</strong> en perfusion lente dans un soluté glucosé à >5%. Il est fondamental de ne <strong>jamais l'administrer en intramusculaire</strong> (risque de nécrose). Le protocole comprend une <strong>dose de charge de 16-17 mg/kg sur 4 heures</strong>, suivie de 8 mg/kg toutes les 8 heures en perfusion de 4 heures. Un <strong>relais per os par ACT</strong> est effectué dès l'arrêt des vomissements. Une surveillance de l'<strong>ECG (QT)</strong> et de la <strong>glycémie</strong> est nécessaire en raison du risque d'hypoglycémie iatrogène.</p>"},{"i":"339473236326","n":170,"o":"170-8","u":"Prise en charge","t":"Conditions de prescription d'un traitement curatif d'un accès simple","q":"Quel est le traitement de première intention d'un accès palustre simple sans vomissement chez un adulte non-gravide, et quelles sont les précautions spécifiques à prendre ?","a":"<p>Le traitement de première intention est une <strong>thérapie combinée à base d'artémisinine (ACT)</strong>, comme l'<strong>artéméther-luméfantrine</strong> (Riamet®) ou l'<strong>arténimol-pipéraquine</strong> (Eurartesim®), pour une durée de <strong>3 jours</strong>. Un <strong>ECG préalable est obligatoire</strong> en raison du risque d'allongement du QT.</p>"},{"i":"513cdb203516","n":170,"o":"170-8","u":"Prise en charge","t":"Conditions de prescription d'un traitement curatif d'un accès simple","q":"Quels sont les critères permettant exceptionnellement d'envisager un traitement ambulatoire pour un accès palustre simple ?","a":"<p>Les critères d'éligibilité à un traitement ambulatoire sont rares et incluent :</p><ul><li>Une <strong>équipe soignante entraînée</strong>.</li><li>Une <strong>première prise bien tolérée</strong> sous surveillance.</li><li>Une <strong>famille fiable</strong> pour la prise en charge.</li><li>Un <strong>suivi possible</strong> à J3, J7 et J28.</li><li>Un <strong>diagnostic d'espèce fiable</strong>.</li><li>L'<strong>absence d'échec</strong> d'un précédent traitement.</li></ul><p>Par défaut, une hospitalisation d'au moins 24 heures est recommandée.</p>"},{"i":"5aa38d8cc6a5","n":170,"o":"170-8","u":"Prise en charge","t":"Conditions de prescription d'un traitement curatif d'un accès simple","q":"Quelles sont les spécificités du traitement du paludisme chez la femme enceinte selon le terme de la grossesse ?","a":"<ul><li>Au <strong>1er trimestre</strong> : <strong>hospitalisation</strong> et traitement par <strong>quinine</strong> (référence) ou atovaquone-proguanil à défaut. Les ACT sont <strong>contre-indiqués</strong>.</li><li>À partir du <strong>2ème trimestre</strong> : l'<strong>artéméther-luméfantrine</strong> est privilégié.</li></ul>"},{"i":"8db5a84032d2","n":170,"o":"170-8","u":"Prise en charge","t":"Conditions de prescription d'un traitement curatif d'un accès simple","q":"Quelle est la particularité pharmacologique des antipaludiques utilisés dans le traitement curatif d'un accès simple au paludisme ?","a":"<p>Tous les antipaludiques utilisés dans l'accès simple sont des <strong>schizonticides sanguins</strong>. La <strong>primaquine</strong>, agissant sur les formes hépatiques quiescentes (hypnozoïtes de <em>P. vivax</em> et <em>P. ovale</em>), n'est utilisée que dans la prévention des rechutes et non pour le traitement de l'accès.</p>"}]};